<?php
namespace App\Services;
use App\Models\EditorialCalendarEvent;use App\Models\EditorialPitch;use App\Models\NewsArticle;use Carbon\Carbon;
class EditorialCalendarService{
 public function range(string $view,Carbon $date):array{return match($view){'day'=>[$date->copy()->startOfDay(),$date->copy()->endOfDay()],'week'=>[$date->copy()->startOfWeek(),$date->copy()->endOfWeek()],default=>[$date->copy()->startOfMonth()->startOfWeek(),$date->copy()->endOfMonth()->endOfWeek()]};}
 public function items(Carbon $from,Carbon $to):array{$items=collect();EditorialPitch::with('assignee')->whereBetween('due_at',[$from,$to])->get()->each(fn($p)=>$items->push(['date'=>$p->due_at,'type'=>'pitch','title'=>$p->title,'responsible'=>$p->assignee?->name,'url'=>route('admin.editorial-pitches.edit',$p),'overdue'=>$p->due_at->isPast()&&!in_array($p->status,['published','discarded'])]));NewsArticle::with('author')->whereBetween('scheduled_for',[$from,$to])->get()->each(fn($n)=>$items->push(['date'=>$n->scheduled_for,'type'=>'news','title'=>$n->title,'responsible'=>$n->author?->name,'url'=>route('admin.news.workflow.show',$n),'overdue'=>$n->scheduled_for->isPast()&&$n->status!=='published']));EditorialCalendarEvent::with('responsible')->whereBetween('starts_at',[$from,$to])->get()->each(fn($e)=>$items->push(['date'=>$e->starts_at,'type'=>$e->is_ai_suggestion?'suggestion':$e->event_type,'title'=>$e->title,'responsible'=>$e->responsible?->name,'url'=>null,'overdue'=>false,'status'=>$e->status]));return $items->sortBy('date')->groupBy(fn($i)=>$i['date']->format('Y-m-d'))->all();}
}
